import type { AnomalyRecord, AnomalySource } from "@/types/home";
import arubaRaw from "@/data/homes/generated/aruba-anomalies.json";
import milanRaw from "@/data/homes/generated/milan-anomalies.json";

/**
 * Anomalies detected on real CASAS monitoring days (no injected anomalies).
 * Generated by `python -m har.export_anomalies` (run from ml/) after
 * `python -m har.run_anomaly`; see ml/results/anomaly.md for how they are evaluated.
 */
interface ExportedAnomalies extends AnomalySource {
  anomalies: (AnomalyRecord & { kind: string })[];
}

export interface RealAnomalies {
  anomalies: AnomalyRecord[];
  source: AnomalySource;
}

function toRealAnomalies(raw: ExportedAnomalies): RealAnomalies {
  const { anomalies, ...source } = raw;
  return {
    anomalies: anomalies.map((a) => ({
      ...a,
      severity: a.severity as AnomalyRecord["severity"],
    })),
    source,
  };
}

export const arubaRealAnomalies = toRealAnomalies(arubaRaw as ExportedAnomalies);
export const milanRealAnomalies = toRealAnomalies(milanRaw as ExportedAnomalies);
